<script type="application/ld+json">
{"@context": "https://schema.org", "@type": "FAQPage", "mainEntity": [{"@type": "Question", "name": "Как размещаются закупки по гособоронзаказу?", "acceptedAnswer": {"@type": "Answer", "text": "По правилам 44-ФЗ с особенностями: преимущественно закрытыми способами (закрытый конкурс или аукцион), у единственного поставщика, определённого актами Правительства или Президента, либо по особому порядку, установленному Правительством на основании статьи 111 44-ФЗ."}}, {"@type": "Question", "name": "Почему закупок ГОЗ нет в ЕИС?", "acceptedAnswer": {"@type": "Answer", "text": "Большинство оборонных закупок проводят закрытыми способами. Сведения о закрытых закупках (сроки, цена, содержание) не размещаются в Единой информационной системе и других открытых источниках — документацию предоставляют только приглашённым участникам."}}, {"@type": "Question", "name": "Что такое АСТ ГОЗ?", "acceptedAnswer": {"@type": "Answer", "text": "Это специализированная электронная площадка (автоматизированная система торгов государственного оборонного заказа), отобранная для проведения закрытых закупок по гособоронзаказу. Торги на ней закрытые и в открытых источниках не отображаются."}}, {"@type": "Question", "name": "Кто такие головной исполнитель и исполнитель?", "acceptedAnswer": {"@type": "Answer", "text": "Головной исполнитель — юрлицо, заключившее контракт по гособоронзаказу напрямую с государственным заказчиком. Исполнитель — участник кооперации, который поставляет продукцию по договору с головным исполнителем или другим исполнителем."}}, {"@type": "Question", "name": "Можно ли отказаться от контракта по гособоронзаказу у единственного поставщика?", "acceptedAnswer": {"@type": "Answer", "text": "Для гособоронзаказа действует принцип обязательности: исполнитель, определённый актами Президента или Правительства, не вправе отказаться от заключения такого контракта (статья 93 44-ФЗ)."}}, {"@type": "Question", "name": "Как считают цену продукции по гособоронзаказу?", "acceptedAnswer": {"@type": "Answer", "text": "Цена продукции государственно регулируется. Применяют разные виды цен (ориентировочная, фиксированная, возмещающая издержки) и методы их расчёта по правилам Правительства; обоснование цены — обязательная часть контракта, особенно с единственным исполнителем."}}, {"@type": "Question", "name": "Нужен ли отдельный счёт для расчётов по ГОЗ?", "acceptedAnswer": {"@type": "Answer", "text": "Да. Расчёты по гособоронзаказу ведут через отдельный счёт в специальном режиме — банковском (уполномоченные банки) или казначейском, с ограничениями по операциям."}}, {"@type": "Question", "name": "Что нужно, чтобы участвовать в закрытой закупке ГОЗ?", "acceptedAnswer": {"@type": "Answer", "text": "Соответствующие допуски (при гостайне — лицензия), аккредитация на специализированной площадке и приглашение заказчика. Также понадобятся отдельный счёт и раздельный учёт при исполнении контракта."}}]}
</script>
